export function dcCoverUrl(fid: string): string {
  const f = DC_FLYERS[fid];
  return f ? 'https:' + f.c : '';
}

export function dcLogoUrl(slug: string): string {
  return `https://it-it-media.shopfully.cloud/images/catene/segnalino_${slug}@2x.png`;
}

export function dcPageUrl(fid: string, pageIdx: number, level: 1 | 4): string {
  const f = DC_FLYERS[fid];
  if (!f) return "";
  const pg = f.p[pageIdx];
  if (!pg) return "";
  const hash = level === 1 ? pg[0] : pg[1];
  return `https://it-it-media-publications.shopfully.cloud/publications/page_assets/${f.i}/${pageIdx + 1}/page_${pageIdx + 1}_level_${level}_${hash}.jpeg`;
}